const listScopedJobProblems = `-- name: ListScopedJobProblems :many
SELECT j.id AS job_id, j.repository_id, r.full_name AS repository_full_name,
       CAST(j.finished_at AS TEXT) AS finished_at,
       (SELECT jr.error_message FROM job_runs jr WHERE jr.job_id = j.id ORDER BY jr.attempt DESC LIMIT 1) AS error_message
FROM jobs j
JOIN repositories r ON r.id = j.repository_id
JOIN installations i ON i.id = r.installation_id
WHERE r.removed_at IS NULL
  AND i.status <> 'removed'
  AND (?1 = 1 OR j.repository_id IN (SELECT s.value FROM json_each(?2) s))
  AND j.state = 'failed'
  AND j.id = (
    SELECT l.id FROM jobs l
    WHERE l.repository_id = j.repository_id AND l.state IN ('succeeded', 'failed')
    ORDER BY l.finished_at DESC, l.id DESC
    LIMIT 1
  )
ORDER BY j.finished_at DESC, j.id DESC
`

type ListScopedJobProblemsParams struct {
	AllRepositories interface{} `json:"all_repositories"`
	ScopeIds        interface{} `json:"scope_ids"`
}

type ListScopedJobProblemsRow struct {
	JobID              string         `json:"job_id"`
	RepositoryID       string         `json:"repository_id"`
	RepositoryFullName string         `json:"repository_full_name"`
	FinishedAt         string         `json:"finished_at"`
	ErrorMessage       sql.NullString `json:"error_message"`
}

// The repositories whose latest finished job failed (the job_failed problem, specs.html section
// 7.7), with the error of that job's last attempt. A repository that left its installation has
// no problem.
func (q *Queries) ListScopedJobProblems(ctx context.Context, arg ListScopedJobProblemsParams) ([]ListScopedJobProblemsRow, error) {
	rows, err := q.db.QueryContext(ctx, listScopedJobProblems, arg.AllRepositories, arg.ScopeIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListScopedJobProblemsRow
	for rows.Next() {
		var i ListScopedJobProblemsRow
		if err := rows.Scan(
			&i.JobID,
			&i.RepositoryID,
			&i.RepositoryFullName,
			&i.FinishedAt,
			&i.ErrorMessage,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listScopedJobs = `-- name: ListScopedJobs :many
SELECT j.id, j.repository_id, r.full_name AS repository_full_name, j.kind, j.state, j.priority, j."trigger",
       j.matched_markers, j.attempts, j.created_at, j.started_at, j.finished_at, j.webhook_received_at
FROM jobs j
JOIN repositories r ON r.id = j.repository_id
WHERE (?1 = 1 OR j.repository_id IN (SELECT s.value FROM json_each(?2) s))
  AND (?3 = '' OR j.repository_id = ?3)
  AND (?4 = '' OR j.state = ?4)
ORDER BY j.created_at DESC, j.id DESC
LIMIT ?6 OFFSET ?5
`

type ListScopedJobsParams struct {
	AllRepositories interface{} `json:"all_repositories"`
	ScopeIds        interface{} `json:"scope_ids"`
	RepositoryID    interface{} `json:"repository_id"`
	State           interface{} `json:"state"`
	PageOffset      int64       `json:"page_offset"`
	PageSize        int64       `json:"page_size"`
}

type ListScopedJobsRow struct {
	ID                 string         `json:"id"`
	RepositoryID       string         `json:"repository_id"`
	RepositoryFullName string         `json:"repository_full_name"`
	Kind               string         `json:"kind"`
	State              string         `json:"state"`
	Priority           string         `json:"priority"`
	Trigger            string         `json:"trigger"`
	MatchedMarkers     sql.NullString `json:"matched_markers"`
	Attempts           int64          `json:"attempts"`
	CreatedAt          string         `json:"created_at"`
	StartedAt          sql.NullString `json:"started_at"`
	FinishedAt         sql.NullString `json:"finished_at"`
	WebhookReceivedAt  sql.NullString `json:"webhook_received_at"`
}

// The jobs of the caller's scope, newest first (specs.html section 7.7): all_repositories is 1 for
// the admin scope, and otherwise a job needs a repository in scope_ids, a JSON array of
// repository ids where an empty one matches none. Empty repository_id and state arguments filter
// nothing. The history of a repository that left its installation is kept and listed.
func (q *Queries) ListScopedJobs(ctx context.Context, arg ListScopedJobsParams) ([]ListScopedJobsRow, error) {
	rows, err := q.db.QueryContext(ctx, listScopedJobs,
		arg.AllRepositories,
		arg.ScopeIds,
		arg.RepositoryID,
		arg.State,
		arg.PageOffset,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListScopedJobsRow
	for rows.Next() {
		var i ListScopedJobsRow
		if err := rows.Scan(
			&i.ID,
			&i.RepositoryID,
			&i.RepositoryFullName,
			&i.Kind,
			&i.State,
			&i.Priority,
			&i.Trigger,
			&i.MatchedMarkers,
			&i.Attempts,
			&i.CreatedAt,
			&i.StartedAt,
			&i.FinishedAt,
			&i.WebhookReceivedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const pruneFinishedJobs = `-- name: PruneFinishedJobs :execrows
DELETE FROM jobs
WHERE id IN (
  SELECT old.id FROM jobs old
  WHERE old.state IN ('succeeded', 'failed')
    AND old.finished_at IS NOT NULL
    AND old.finished_at < ?1
  ORDER BY old.finished_at, old.id
  LIMIT ?2
)
`

type PruneFinishedJobsParams struct {
	Cutoff sql.NullString `json:"cutoff"`
	Batch  int64          `json:"batch"`
}

// Retention (specs.html section 4.6): a job in a terminal state that finished before the cutoff is
// deleted with its job_runs and job_events (the foreign keys cascade). A queued or running job is
// never matched, whatever its age. The oldest go first and a batch is bounded, so a pass over a
// long history takes a number of small deletes and never one large one.
func (q *Queries) PruneFinishedJobs(ctx context.Context, arg PruneFinishedJobsParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, pruneFinishedJobs, arg.Cutoff, arg.Batch)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const requeueJob = `-- name: RequeueJob :execrows
UPDATE jobs
SET state = 'queued',
    attempts = ?1,
    run_after = ?2,
    priority = ?3,
    "trigger" = ?4,
    matched_markers = ?5,
    webhook_received_at = ?6,
    rerun_requested = 0,
    rerun_trigger = NULL,
    rerun_markers = NULL,
    rerun_webhook_received_at = NULL,
    lease_owner = NULL,
    lease_expires_at = NULL,
    last_heartbeat_at = NULL,
    started_at = NULL
WHERE id = ?7
  AND state = 'running'
`

type RequeueJobParams struct {
	Attempts          int64          `json:"attempts"`
	RunAfter          string         `json:"run_after"`
	Priority          string         `json:"priority"`
	Trigger           string         `json:"trigger"`
	MatchedMarkers    sql.NullString `json:"matched_markers"`
	WebhookReceivedAt sql.NullString `json:"webhook_received_at"`
	ID                string         `json:"id"`
}

// A requeued job is the follow-up of a trigger that arrived while it ran: the caller passes the
// priority, trigger, markers and webhook arrival with that trigger merged in, and what the
// mid-run triggers recorded is cleared.
func (q *Queries) RequeueJob(ctx context.Context, arg RequeueJobParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, requeueJob,
		arg.Attempts,
		arg.RunAfter,
		arg.Priority,
		arg.Trigger,
		arg.MatchedMarkers,
		arg.WebhookReceivedAt,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

